import net from "node:net";
import crypto from "node:crypto";
import http from "node:http";

const expr = process.argv[2];
const wsUrl = await new Promise((res) => {
  http.get("http://localhost:9222/json", (r) => {
    let d = ""; r.on("data", (c) => (d += c)); r.on("end", () => {
      const pages = JSON.parse(d).filter((p) => p.webSocketDebuggerUrl);
      res(pages[0].webSocketDebuggerUrl);
    });
  });
});
const { hostname, port, pathname } = new URL(wsUrl);
const key = crypto.randomBytes(16).toString("base64");
const sock = net.connect(Number(port), hostname, () => {
  sock.write(
    `GET ${pathname} HTTP/1.1\r\nHost: ${hostname}:${port}\r\nUpgrade: websocket\r\n` +
    `Connection: Upgrade\r\nSec-WebSocket-Key: ${key}\r\nSec-WebSocket-Version: 13\r\n\r\n`
  );
});

function maskedFrame(payload) {
  const data = Buffer.from(payload);
  const mask = crypto.randomBytes(4);
  const len = data.length;
  let header;
  if (len < 126) header = Buffer.from([0x81, 0x80 | len]);
  else { header = Buffer.from([0x81, 0x80 | 126, len >> 8, len & 0xff]); }
  const masked = Buffer.alloc(len);
  for (let i = 0; i < len; i++) masked[i] = data[i] ^ mask[i % 4];
  return Buffer.concat([header, mask, masked]);
}

let upgraded = false, buf = Buffer.alloc(0);
sock.on("data", (chunk) => {
  buf = Buffer.concat([buf, chunk]);
  if (!upgraded) {
    const i = buf.indexOf("\r\n\r\n");
    if (i < 0) return;
    upgraded = true; buf = buf.slice(i + 4);
    sock.write(maskedFrame(JSON.stringify({
      id: 1, method: "Runtime.evaluate",
      params: { expression: expr, returnByValue: true, awaitPromise: true },
    })));
  }
  // parse one unmasked text frame from server
  while (buf.length >= 2) {
    let len = buf[1] & 0x7f, off = 2;
    if (len === 126) { len = buf.readUInt16BE(2); off = 4; }
    else if (len === 127) { len = Number(buf.readBigUInt64BE(2)); off = 10; }
    if (buf.length < off + len) return;
    const payload = buf.slice(off, off + len).toString();
    buf = buf.slice(off + len);
    try {
      const msg = JSON.parse(payload);
      if (msg.id === 1) {
        console.log(JSON.stringify(msg.result?.result?.value ?? msg.result ?? msg, null, 2));
        sock.end(); process.exit(0);
      }
    } catch { /* keep reading */ }
  }
});
setTimeout(() => { console.error("timeout"); process.exit(1); }, 8000);

